import unittest
from launch.config import load_config
from launch.cli import options

class ConfigTests(unittest.TestCase):
    def test_environment_types(self):
        self.assertEqual(load_config({'APP_PORT':'9000', 'APP_DEBUG':'false'}),
                         {'host':'localhost', 'port':9000, 'debug':False})
    def test_cli_precedence(self):
        env = {'APP_HOST':'example', 'APP_PORT':'9000', 'APP_DEBUG':'yes'}
        self.assertEqual(options(['--no-debug'], env),
                         {'host':'example', 'port':9000, 'debug':False})

    def test_cli_port_boundaries(self):
        for port in (1, 65535):
            with self.subTest(port=port):
                env = {'APP_PORT': '9000'}
                self.assertEqual(options(['--port', str(port)], env)['port'], port)
                self.assertEqual(env, {'APP_PORT': '9000'})

    def test_cli_rejects_out_of_range_ports(self):
        for port in (-1, 0, 65536):
            with self.subTest(port=port):
                with self.assertRaises(ValueError):
                    options(['--port', str(port)], {'APP_PORT': '9000'})

