import unittest
from decimal import Decimal
from invoices.reader import read_rows
from invoices.summary import totals

class InvoiceTests(unittest.TestCase):
    def test_quoted_names(self):
        rows = read_rows('customer,amount,status\n"Acme, Inc",1.25, PAID \n')
        self.assertEqual(rows, [{'customer':'Acme, Inc','amount':Decimal('1.25'),'status':'paid'}])
    def test_exact_totals(self):
        self.assertEqual(totals('customer,amount,status\nb,0.105,paid\nb,0.105,paid\na,100,cancelled\n'), {'b':'0.21'})

